describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            99.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", undefined, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects first bracket (weight ≤ 500g)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 250, 2)]; // 500g exactly
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects second bracket (weight between 501g and 2000g)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 501, 1)]; // 501g
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("selects bracket at exact boundary (2000g)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 2)]; // 2000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 3000, 2)]; // 6000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("defaults overflow to last bracket cost when not specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 3000, 2)]; // 6000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      const lines = [makeLine("a", 400, 1)]; // 400g → first bracket
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product with given quantity", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product twice", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product(), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws for non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 0)).toThrow(RangeError);
      expect(() => cart.add(product(), -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
    });

    it("throws for negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(
        RangeError,
      );
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(cart.remove("p1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for product not in cart", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 1)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copies that don't affect cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 999;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
      cart.add(product({ id: "b", unitPriceCents: 300 }), 3);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1900); // 1000 + 900
    });

    it("applies discount policy and clamps to [0, subtotal]", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(200);
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("clamps discount exceeding subtotal to subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 9999,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().discountCents).toBe(1000);
    });

    it("computes tax on discounted subtotal", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      cart.totals();
      // Tax computed on discounted subtotal: 1000 - 200 = 800
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    });

    it("passes lines and discounted subtotal to shipping", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        900, // discounted subtotal
      );
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => 72,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1000);
      expect(t.discountCents).toBe(100);
      expect(t.taxCents).toBe(72);
      expect(t.shippingCents).toBe(500);
      expect(t.totalCents).toBe(900 + 72 + 500); // 1472
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => -50,
      };
      const cart = new Cart({ taxCalculator });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("uses default region US when not specified", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(product(), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });
  });
});

