toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("computeTaxCents(%i, %s) returns 0", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate below 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects defaultRate above 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects rate below 0 for a region", () => {
      expect(() => new RegionalTaxCalculator({ "US": -0.01 })).toThrow(RangeError);
    });

    it("rejects rate above 1 for a region", () => {
      expect(() => new RegionalTaxCalculator({ "US": 1.5 })).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 0.0875, "FR": 0.2 }, 0.1),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, "DE": 0.19 },
      0.05,
    );

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-1000, "US-CA")).toBe(0);
    });

    it("uses region-specific rate (8.75% of 10000 = 875)", () => {
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("uses default rate for unknown region (5% of 10000 = 500)", () => {
      expect(calc.computeTaxCents(10000, "JP")).toBe(500);
    });

    it("rounds down (19% of 999 = 189.81 → 189)", () => {
      expect(calc.computeTaxCents(999, "DE")).toBe(189);
    });

    it("uses default 0 when no defaultRate specified", () => {
      const noDefault = new RegionalTaxCalculator({ "US": 0.1 });
      expect(noDefault.computeTaxCents(1000, "FR")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = { getRate: vi.fn() };
    const calc = new AsyncTaxCalculator(provider);
    const result = await calc.computeTaxCents(0, "US");
    expect(result).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = { getRate: vi.fn() };
    const calc = new AsyncTaxCalculator(provider);
    const result = await calc.computeTaxCents(-100, "US");
    expect(result).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("computes tax using provider rate (10% of 2000 = 200)", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(2000, "US")).toBe(200);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down (8.75% of 999 = 87.4125 → 87)", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(999, "US-CA")).toBe(87);
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "XX")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for rate < 0", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "XX")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "XX")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network down")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("network down");
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty array", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 3 },
    ];
    // 200*2 + 500*3 = 400 + 1500 = 1900
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats undefined weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

