import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals and lines for a simple cart", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].quantity).toBe(2);
    });
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
    });

    it("throws RangeError for invalid fetched price (negative)", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-1),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws RangeError for non-integer fetched price", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9.99),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
    });
  });

  describe("inventoryChecker", () => {
    it("proceeds when all items are available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product(), 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(3);
        expect(err.available).toBe(0);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product(), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 2,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
      }
    });

    it("checks inventory after price refresh", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const callOrder: string[] = [];
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation(async () => {
          callOrder.push("fetch");
          return 1000;
        }),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockImplementation(async () => {
          callOrder.push("check");
          return { available: true };
        }),
      };
      await cart.checkout({ priceFetcher, inventoryChecker });
      expect(callOrder).toEqual(["fetch", "check"]);
    });
  });

  describe("asyncTaxProvider", () => {
    it("uses async tax provider for totals computation", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100); // 10% of 1000
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 200 },
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // Discounted subtotal = 800, tax = 10% of 800 = 80
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
    });

    it("includes shipping in async totals", async () => {
      const cart = new Cart({
        shippingCalculator: { computeShippingCents: () => 500 },
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.taxCents).toBe(50); // 5% of 1000
      expect(result.totals.totalCents).toBe(1000 + 50 + 500);
    });

    it("propagates async tax provider rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service down",
      );
    });

    it("throws RangeError for invalid async tax rate", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("InventoryError shape", () => {
    it("has name, productId, requested, and available fields", () => {
      const err = new InventoryError("test", "abc", 5, 2);
      expect(err.name).toBe("InventoryError");
      expect(err.message).toBe("test");
      expect(err.productId).toBe("abc");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
      expect(err).toBeInstanceOf(Error);
    });

    it("available can be undefined", () => {
      const err = new InventoryError("no stock", "xyz", 3, undefined);
      expect(err.available).toBeUndefined();
    });
  });
});

