import { describe, it, expect, vi } from "vitest";
import { refreshPrices, InventoryError } from "../src/inventory.ts";
import type { PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("refreshPrices", () => {
  const makeLine = (id: string, price: number, qty: number): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  });

  it("updates prices from fetcher", async () => {
    const lines = [makeLine("a", 100, 2), makeLine("b", 200, 1)];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async (id: string) => {
        return id === "a" ? 150 : 250;
      }),
    };
    const refreshed = await refreshPrices(lines, fetcher);
    expect(refreshed[0].product.unitPriceCents).toBe(150);
    expect(refreshed[1].product.unitPriceCents).toBe(250);
    expect(refreshed[0].quantity).toBe(2);
    expect(refreshed[1].quantity).toBe(1);
  });

  it("preserves product fields other than unitPriceCents", async () => {
    const lines: CartLine[] = [
      {
        product: { id: "x", name: "Thing", unitPriceCents: 100, weightGrams: 500, currency: "EUR" },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };
    const refreshed = await refreshPrices(lines, fetcher);
    expect(refreshed[0].product.name).toBe("Thing");
    expect(refreshed[0].product.weightGrams).toBe(500);
    expect(refreshed[0].product.currency).toBe("EUR");
  });

  it("throws RangeError for negative price", async () => {
    const lines = [makeLine("a", 100, 1)];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const lines = [makeLine("a", 100, 1)];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN price", async () => {
    const lines = [makeLine("a", 100, 1)];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(NaN),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = { fetchPriceCents: vi.fn() };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("propagates fetcher rejection", async () => {
    const lines = [makeLine("a", 100, 1)];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("timeout")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("timeout");
  });

  it("accepts zero as a valid price", async () => {
    const lines = [makeLine("free", 100, 1)];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(0),
    };
    const refreshed = await refreshPrices(lines, fetcher);
    expect(refreshed[0].product.unitPriceCents).toBe(0);
  });
});

describe("InventoryError", () => {
  it("extends Error with proper fields", () => {
    const err = new InventoryError("nope", "prod-1", 10, 3);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("nope");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(10);
    expect(err.available).toBe(3);
  });

  it("available may be undefined", () => {
    const err = new InventoryError("gone", "prod-2", 5, undefined);
    expect(err.available).toBeUndefined();
    expect(err.requested).toBe(5);
  });
});

